#!/usr/bin/env bash
# Gives the files in htdocs/assets names that depend on their content (page.css becomes page.<hash>.css), so that
# they can be cached forever, and writes the mapping to the manifest that Linkrot\Web\Assets reads (app/assets.php).
# usage: scripts/build-assets.sh <htdocs of the build> <app of the build>
set -euo pipefail

htdocs="${1:?usage: build-assets.sh <htdocs> <app>}"
app="${2:?usage: build-assets.sh <htdocs> <app>}"
assets="$htdocs/assets"

manifest="<?php

declare(strict_types=1);

// Generated by scripts/build-assets.sh: logical name to the file in htdocs/assets.
return [
"
for file in "$assets"/*; do
	name="$(basename "$file")"
	hash="$(sha256sum "$file" | cut -c1-12)"
	hashed="${name%.*}.$hash.${name##*.}"
	mv "$file" "$assets/$hashed"
	manifest+="    '$name' => '$hashed',
"
done
manifest+="];
"
printf '%s' "$manifest" >"$app/assets.php"
